"""Random sentences built from a small vocabulary, mixed case, so repeats
and case-sensitivity both show up."""


WORDS = ["cat", "Cat", "dog", "the", "a", "runs", "fast", "slow"]


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 10)
    words = [rng.choice(WORDS) for _ in range(n)]
    return {"name": "%d words from a small vocabulary #%d" % (n, index),
            "stdin": " ".join(words) + "\n"}
